import{_ as o,c as t,o as d,ag as a}from"./chunks/framework.DfL_BkQ-.js";const p=JSON.parse('{"title":"小程序兼容性","description":"","frontmatter":{},"headers":[],"relativePath":"zh-CN/guide/miniapp-compatibility.md","filePath":"zh-CN/guide/miniapp-compatibility.md","lastUpdated":1791311600000}'),c={name:"zh-CN/guide/miniapp-compatibility.md"};function r(i,e,n,l,s,h){return d(),t("div",null,[...e[0]||(e[0]=[a('<h1 id="小程序兼容性" tabindex="-1">小程序兼容性 <a class="header-anchor" href="#小程序兼容性" aria-label="Permalink to &quot;小程序兼容性&quot;">​</a></h1><blockquote><p><strong>这是权威边界。</strong> nPlyr 运行 hikerView 兼容的小程序，但原始引擎是 <strong>Android / Java 运行 Rhino</strong>，而 nPlyr 在 Apple 平台上运行于 <strong>JavaScriptCore</strong> 且<strong>没有 JVM</strong>。nPlyr 原生重实现了桥接与规则 DSL，并为规则所依赖的 Java API 添加了一个 <strong>Rhino → Java 兼容层</strong>。本页阐明哪些保持不变、哪些<em>通过</em>兼容层（带注意事项）工作，以及哪些<strong>不</strong>被支持。</p></blockquote><p>如果你只是想试用某条规则的用户，请先阅读<a href="/zh-CN/guide/miniapps.html">小程序</a>。本页用于理解<em>为什么</em>某条规则可能与它在 Android 上的行为不同。</p><h2 id="为什么存在边界" tabindex="-1">为什么存在边界 <a class="header-anchor" href="#为什么存在边界" aria-label="Permalink to &quot;为什么存在边界&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>hikerView（Android）</th><th>nPlyr（Apple）</th></tr></thead><tbody><tr><td>JS 引擎</td><td><strong>Rhino</strong>（内嵌 Java）</td><td><strong>JavaScriptCore</strong></td></tr><tr><td>能调用 Java 吗？</td><td>能——<code>Packages.*</code>、<code>new JavaImporter()</code>、<code>with(){}</code> 进入任意类</td><td>无 JVM。一个<strong>兼容垫片</strong>模拟了 Java API 的<em>子集</em></td></tr><tr><td>UI</td><td>Android <code>Activity</code> / <code>RecyclerView</code></td><td>原生 SwiftUI</td></tr><tr><td>网络 / 存储</td><td>OkGo / LitePal</td><td>URLSession / UserDefaults</td></tr></tbody></table><p>因此<em>逻辑</em>是 1:1 移植的（DSL、<code>fba</code> 桥接契约、<code>hiker://</code> 路由），但任何运行时触及 <strong>Java</strong> 的部分都必须重新提供——而这正是刻意的一个<strong>经过筛选的子集</strong>，而非完整的 JRE。</p><p>nPlyr 原生重实现了桥接与规则 DSL，并添加了一个兼容层，模拟规则所依赖的 Java API 的筛选子集。</p><h2 id="✅-完全支持——无需改动" tabindex="-1">✅ 完全支持——无需改动 <a class="header-anchor" href="#✅-完全支持——无需改动" aria-label="Permalink to &quot;✅ 完全支持——无需改动&quot;">​</a></h2><p>以下与 Android 上行为一致；仅使用这些的规则会&quot;开箱即用&quot;：</p><ul><li><strong>规则 DSL</strong>：<code>pdfh</code> / <code>pdfa</code> / <code>pd</code> 选择器、<code>parseDom</code>、<code>setHomeResult</code> / <code>setSearchResult</code> / <code>setResult</code>。</li><li><strong><code>$</code> 选择器层</strong>——包括 <code>$(url).lazyRule(fn)</code>、<code>$(url, ordinary).lazyRule</code> 与 <code>.rule(fn)</code>。</li><li><strong><code>fy_bridge_app</code>（<code>fba</code>）桥</strong>：播放、<code>fetch</code>、<code>post</code>、<code>request</code>、解析、变量存储。</li><li><strong><code>hiker://</code> 路由</strong>，包括 <code>hiker://empty##…</code>（轻量参数载体）与 <code>hiker://search?s=</code>（聚合搜索）。</li><li><strong><code>col_type</code> 渲染</strong>——全部 <strong>38 种布局</strong>，与 hikerView 自有的条目模板对齐。</li><li><strong>变量映射</strong>：<code>putVar</code> / <code>getVar</code> / <code>putMyVar</code> / <code>getMyVar</code>（内存）与 <code>setItem</code> / <code>getItem</code> / <code>clearItem</code>（持久化到本地存储）。</li><li><strong>HTTP</strong>：带请求头的 <code>fetch</code> / <code>post</code>；字符集处理（<code>gb2312</code> / <code>gbk</code> / <code>gb18030</code> → GBK，<code>big5</code> → Big5，默认 UTF-8）；<code>withHeaders</code> / <code>onlyHeaders</code> / <code>withStatusCode</code> 返回 JSON 信封。</li><li><strong>User-Agent</strong>：<code>auto</code> / <code>mobile</code> / <code>pc</code> / 自定义（当你选择跟随时，规则自身的 UA 生效）。</li><li><strong>云分享</strong>：TextDB（云2）、<code>cmd.im</code> 302 重定向（云5）、<code>pasteme</code>（云6）。</li><li><strong>纯 JS 的加密</strong>（<code>AES</code>、<code>CryptoJS</code>）；由原生桥提供时的 <code>RSA</code>。</li><li><strong><code>;post;</code> 预抓取</strong>与 <code>decodeConflictStr</code> 解码。</li></ul><h2 id="⚠️-通过-java-兼容层支持-仅子集" tabindex="-1">⚠️ 通过 Java 兼容层支持（仅子集） <a class="header-anchor" href="#⚠️-通过-java-兼容层支持-仅子集" aria-label="Permalink to &quot;⚠️ 通过 Java 兼容层支持（仅子集）&quot;">​</a></h2><p>该层提供以下全局对象与类，但各有注意事项：</p><ul><li><strong>全局对象</strong>：<code>Packages</code>、<code>java</code>、<code>JavaImporter</code>、<code>importPackage()</code>、<code>importClass()</code>。</li><li><strong><code>_base64</code></strong>——模拟 <code>android.util.Base64</code> 的语义。</li><li><strong><code>FileUtil</code></strong>（<code>com.example.hikerview.utils</code>）——作为<em>原生垫片</em>提供（见下文的 <code>toInputStream</code>）。</li><li><strong><code>javax.crypto</code></strong>：<code>Cipher.getInstance</code> / <code>init</code> / <code>doFinal</code>、<code>SecretKeySpec</code>、<code>IvParameterSpec</code>——但 <strong><code>Cipher.update</code> 未实现</strong>（它会抛出一个清晰的&quot;语料库未使用，请报告规则名称&quot;错误，而不是静默出错）。</li></ul><h3 id="已知类列表-重点" tabindex="-1">已知类列表（重点） <a class="header-anchor" href="#已知类列表-重点" aria-label="Permalink to &quot;已知类列表（重点）&quot;">​</a></h3><p>只垫片化了<strong>经过筛选的一组</strong> Java 类。列表之外的类会回退到一个<strong>诊断桩</strong>：它记录一次日志，并在被使用时抛出<em>清晰</em>的错误——而<strong>不会</strong>产生裸露的 <code>ReferenceError</code>。实践中这意味着：</p><ul><li>使用常见、知名 Java 类（语料库所需的那些）的规则可以工作。</li><li>触及冷门或 Android 框架类的规则会以一条可操作的消息失败，指明缺失的类——请报告规则名称，以便列表得以扩充。</li></ul><h3 id="byte-有两种表示" tabindex="-1"><code>byte[]</code> 有两种表示 <a class="header-anchor" href="#byte-有两种表示" aria-label="Permalink to &quot;`byte[]` 有两种表示&quot;">​</a></h3><p>这一点尤其会让图片解密规则踩坑：</p><ul><li><strong>小缓冲区（≤ 4096 B）</strong>→ 真正的 JS <code>Array&lt;number&gt;</code>，带有 <code>.length</code> <em>属性</em>（Java 数组语义），并且位运算可用（例如某类图片解密规则中常见的 <code>toHex</code> 写法）。</li><li><strong>大缓冲区（图片等）</strong>→ 一个宿主提供的字节数组对象，仅暴露 <code>length</code> / <code>toBase64</code> / <code>toHex</code> / <code>utf8String</code> / <code>slice</code>。你<strong>无法</strong>对大形式做逐字节访问——第三方图片解密链路依赖的是宿主方法。</li></ul><h3 id="fileutil-toinputstream-漫画图片解密" tabindex="-1"><code>FileUtil.toInputStream</code>（漫画图片解密） <a class="header-anchor" href="#fileutil-toinputstream-漫画图片解密" aria-label="Permalink to &quot;`FileUtil.toInputStream`（漫画图片解密）&quot;">​</a></h3><p>在 Android 上它返回一个 Java <code>InputStream</code>。nPlyr <strong>替换</strong>了这条路径：它拦截一个被拦截流的标记，将其转换为从应用缓存提供的本地图片 URL，并将图片交回视图。期望<em>自己读取流</em>的规则必须依赖这个宿主转换，而不是去打开一个 <code>InputStream</code>。</p><h3 id="java-文件-i-o-极简" tabindex="-1">Java 文件 I/O 极简 <a class="header-anchor" href="#java-文件-i-o-极简" aria-label="Permalink to &quot;Java 文件 I/O 极简&quot;">​</a></h3><p>被模拟的文件根返回 <code>&#39;/&#39;</code>，<code>fileExist</code> 返回布尔值——一个极小的垫片。任意的 <code>java.io.File</code> / NIO / <code>Zip</code> / <code>java.net.*</code> 操作均<strong>不可用</strong>；任何网络相关的事情都请使用 <code>fetch</code> / <code>post</code> 桥。</p><h3 id="bigdecimal-标度" tabindex="-1"><code>BigDecimal</code> 标度 <a class="header-anchor" href="#bigdecimal-标度" aria-label="Permalink to &quot;`BigDecimal` 标度&quot;">​</a></h3><p>Android 的 <code>BigDecimal</code> 保留标度（例如 <code>&quot;5.0&quot;</code>）。nPlyr 的小数格式化也保留标度，否则数字格式会漂移。依赖 Java <code>BigDecimal</code> 精确 <code>toString</code> 输出的规则可能会看到差异。</p><h3 id="rhino-引擎语义" tabindex="-1">Rhino 引擎语义 <a class="header-anchor" href="#rhino-引擎语义" aria-label="Permalink to &quot;Rhino 引擎语义&quot;">​</a></h3><p>顶层 <code>const X = X = …</code> 的双重赋值 Rhino 可以容忍，但会让 <strong>JavaScriptCore 崩溃</strong>。nPlyr 运行一个脚本预处理器，使这类退化 JS 不会拖垮引擎。因此 Rhino 专属的怪癖被中和，而非被模拟。</p><h3 id="hijackenv-的-method-桥" tabindex="-1"><code>hijackEnv</code> 的 <code>method_*</code> 桥 <a class="header-anchor" href="#hijackenv-的-method-桥" aria-label="Permalink to &quot;`hijackEnv` 的 `method_*` 桥&quot;">​</a></h3><p>支持 Java 方法劫持，但原生桥必须委派给它在注入时捕获的<strong>原始方法</strong>——<strong>绝不</strong>回调进 JS 全局，否则会导致无限递归（<code>Maximum call stack size exceeded</code>）。返回 no-op 的桥会静默禁用依赖它的动态卡片。</p><h2 id="❌-不支持" tabindex="-1">❌ 不支持 <a class="header-anchor" href="#❌-不支持" aria-label="Permalink to &quot;❌ 不支持&quot;">​</a></h2><ul><li><strong>已知列表之外的任意 Java 类</strong>——没有 JVM，也无法反射进入 Android 框架。</li><li><strong>Android UI / View / Activity / RecyclerView / Adapter</strong> API——nPlyr 以原生方式渲染；这些没有对应物。</li><li><strong>Android 权限、Content Providers、Intent 系统。</strong></li><li><strong>部分 <code>javax.crypto</code> 路径</strong>——<code>Cipher.update</code>，以及原生桥尚未实现的任何加密模式。</li><li><strong><code>java.io.File</code> / NIO / Zip / <code>java.net.*</code></strong>——请改用 <code>fetch</code> / <code>post</code> 桥。</li></ul><h2 id="报告不兼容" tabindex="-1">报告不兼容 <a class="header-anchor" href="#报告不兼容" aria-label="Permalink to &quot;报告不兼容&quot;">​</a></h2><p>当某条具体规则行为异常时，请记录：</p><ol><li><strong>规则名称</strong>，</li><li>它失败的<strong>步骤</strong>（首页 / 搜索 / 详情 / 解析），以及</li><li><strong>消息</strong>——兼容层会为未列出的类记录一条清晰的一行日志。</li></ol><p>报告这些信息，以便已知类列表与原生桥得以扩充。</p><h2 id="给规则作者的建议" tabindex="-1">给规则作者的建议 <a class="header-anchor" href="#给规则作者的建议" aria-label="Permalink to &quot;给规则作者的建议&quot;">​</a></h2><ul><li>将 <code>java.io.File</code> / 流读取替换为 <code>fetch</code> / <code>post</code> 桥，或替换为返回本地图片 URL 的宿主 <code>toInputStream</code> 转换。</li><li>不要依赖冷门的 Java 类；优先使用 JS 或桥的等价物。</li><li>避免 Rhino 专属的写法，例如 <code>const X = X = …</code> 双重赋值。</li><li>将逐字节的图片处理保持在<strong>小</strong>缓冲区上；大图片请使用 <code>toBase64</code> / <code>toHex</code> / <code>slice</code> 宿主方法。</li></ul><h2 id="海阔视界官方文档" tabindex="-1">海阔视界官方文档 <a class="header-anchor" href="#海阔视界官方文档" aria-label="Permalink to &quot;海阔视界官方文档&quot;">​</a></h2><p>nPlyr 旨在与 hikerView 规则生态兼容。关于完整、权威的参考——规则 DSL、选择器、小程序桥接契约与编写指南——请查阅海阔视界官方文档：</p><ul><li><strong>海阔视界文档：</strong> <a href="https://github.com/ReflectionLab/Documents" target="_blank" rel="noreferrer">https://github.com/ReflectionLab/Documents</a></li></ul><p>来自 hikerView 的规则作者可以使用相同的分享文本与 JSON；上述记录的兼容性边界说明了 nPlyr 在何处偏离 Android 运行时。</p>',41)])])}const u=o(c,[["render",r]]);export{p as __pageData,u as default};
